SELECT x.tableoid::pg_catalog.oid::pg_catalog.text AS catalog_class_oid, x.oid::pg_catalog.text AS object_oid, x.ev_class::pg_catalog.text AS relation_oid, pg_catalog.to_jsonb(x)::pg_catalog.text AS original_catalog_row_json FROM pg_catalog.pg_rewrite x WHERE EXISTS (SELECT 1 FROM pg_catalog.pg_class c WHERE c.oid = x.ev_class AND c.relnamespace = $1::pg_catalog.oid) ORDER BY x.oid